/**
 * Storage interface. Track E implements RedisStore (Upstash); MemoryStore (lib/store/memory.ts)
 * is the in-process implementation for tests and local dev without Redis.
 * Keys and TTLs: docs/design-plan.md §10 (60-day sliding TTL on user data).
 */
import type { ConceptMastery, MasteryMap } from "./engine";
import type {
  ApiMessages,
  AppEvent,
  BossState,
  MomentRecord,
  Session,
  SessionSummary,
  TranscriptItem,
  User,
} from "./session";

export type UsageScope = { kind: "anon"; id: string } | { kind: "ip"; id: string } | { kind: "global" };

export interface Store {
  getUser(anonId: string): Promise<User | null>;
  putUser(user: User): Promise<void>;

  listSessions(anonId: string): Promise<SessionSummary[]>;
  getSession(sessionId: string): Promise<Session | null>;
  putSession(session: Session): Promise<void>;

  getApiMessages(sessionId: string): Promise<ApiMessages>;
  putApiMessages(sessionId: string, messages: ApiMessages): Promise<void>;

  getTranscript(sessionId: string): Promise<TranscriptItem[]>;
  putTranscript(sessionId: string, items: TranscriptItem[]): Promise<void>;

  getMoment(sessionId: string, momentId: string): Promise<MomentRecord | null>;
  listMoments(sessionId: string): Promise<MomentRecord[]>;
  putMoment(moment: MomentRecord): Promise<void>;

  getBoss(sessionId: string, bossId: string): Promise<BossState | null>;
  putBoss(boss: BossState): Promise<void>;

  getMastery(anonId: string): Promise<MasteryMap>;
  putMastery(anonId: string, concept: string, mastery: ConceptMastery): Promise<void>;

  /** Adds spend (micro-USD) for today's date (UTC) to each scope; returns new totals in the same order. */
  addUsage(scopes: UsageScope[], microUsd: number): Promise<number[]>;
  getUsage(scopes: UsageScope[]): Promise<number[]>;

  logEvent(event: AppEvent): Promise<void>;
}
/**
 * Core entities persisted per user/session. See docs/design-plan.md §10.
 */
import type Anthropic from "@anthropic-ai/sdk";
import type { EngineState, Familiarity, UserSettings, BossOutcome } from "./engine";
import type { LearningMomentInput, MomentStatus, MomentType, Verdict } from "./moment";

export interface User {
  anonId: string;
  createdAt: number;
  xp: number;
  level: number;
  unlocks: { themes: string[]; soundPacks: string[] };
  settings: UserSettings;
}

export interface Intent {
  goal: string;
  familiarity: Familiarity;
  minutes: number; // session length target (default 10)
  demo: boolean; // started from the churn demo starter
}

/** Light "session sketch" generated in the background (Opus, high effort). Not a curriculum. */
export interface SessionSketch {
  title: string;
  goalSummary: string;
  novice: boolean;
  milestones: string[]; // 3-5 likely chunks of work
  conceptRadar: { concept: string; whyItMatters: string; likelyMomentType: MomentType }[];
}

export interface StoryBible {
  genre: string;
  tone: string;
  setting: string;
  protagonist: string;
  motif: string; // light theming drawn from the user's work
  arc: string[]; // planned beats
  seeds: { narrator: string; twist: string };
}

export interface StoryChapter {
  id: string;
  trigger: string; // e.g. "boss:<id>" | "wrapup"
  title: string;
  text: string;
  summary: string;
  createdAt: number;
}

export interface StoryState {
  bible?: StoryBible;
  chapters: StoryChapter[];
}

export interface Session {
  id: string;
  anonId: string;
  createdAt: number;
  title: string;
  intent: Intent;
  sketch?: SessionSketch;
  containerId?: string;
  fileIds: string[]; // files produced in this session (ownership check for /api/files/[id])
  demoFileAttached: boolean;
  status: "active" | "wrapped";
  engine: EngineState;
  rollingSummary?: string;
  story: StoryState;
}

/** Full server-side record of a moment (contains answer keys; never sent to the client as-is). */
export interface MomentRecord {
  id: string;
  sessionId: string;
  createdAt: number;
  type: MomentType | "boss";
  candidate: LearningMomentInput; // for boss questions, generated by the boss route in the same shape
  toolUseId?: string; // the learning_moment tool_use block id (work moments)
  bossId?: string;
  status: MomentStatus;
  mcOffered: boolean;
  answer?: string;
  mcChoice?: number;
  verdict?: Verdict;
  why?: string;
  missingPoints?: string[];
  xp?: number;
  answeredAt?: number;
}

export interface BossState {
  id: string;
  sessionId: string;
  name: string; // e.g. "The Overfit Bug"
  ascii: "bug" | "slime" | "ghost";
  intro: string;
  maxHp: number;
  hp: number;
  momentIds: string[];
  outcome?: BossOutcome;
  createdAt: number;
}

/** Renderable transcript item (UI history; separate from the raw API message list). */
export type TranscriptItem =
  | { kind: "user"; id: string; text: string; at: number }
  | { kind: "assistant_text"; id: string; text: string }
  | {
      kind: "code_run";
      id: string; // server_tool_use block id
      language: "bash" | "python" | "file";
      code: string;
      stdout?: string;
      stderr?: string;
      returnCode?: number;
      fileIds: string[];
    }
  | { kind: "moment"; id: string; momentId: string }
  | { kind: "prediction_reveal"; id: string; momentId: string; actualResult: string; verdict: Verdict; why: string; xp: number }
  | { kind: "milestone"; id: string; label: string }
  | { kind: "boss"; id: string; bossId: string }
  | { kind: "story"; id: string; chapterId: string }
  | { kind: "notice"; id: string; text: string };

/** Raw conversation as sent to the Claude API. */
export type ApiMessages = Anthropic.Beta.BetaMessageParam[];

export interface SessionSummary {
  id: string;
  title: string;
  createdAt: number;
  status: Session["status"];
}

export interface AppEvent {
  at: number;
  anonId: string;
  sessionId?: string;
  name:
    | "unlock"
    | "session_created"
    | "moment_proposed"
    | "moment_gated"
    | "moment_shown"
    | "moment_answered"
    | "moment_skipped"
    | "moment_deferred"
    | "moment_reported"
    | "mc_offered"
    | "boss_started"
    | "boss_finished"
    | "session_wrapped"
    | "guardrails_changed"
    | "level_up"
    | "error";
  props?: Record<string, string | number | boolean | null>;
}
/** In-process Store for tests and local dev without Redis. Not durable; per server instance. */
import type { Store, UsageScope } from "@/lib/contracts/store";
import type { ConceptMastery, MasteryMap } from "@/lib/contracts/engine";
import type { ApiMessages, AppEvent, BossState, MomentRecord, Session, SessionSummary, TranscriptItem, User } from "@/lib/contracts/session";

const clone = <T,>(v: T): T => structuredClone(v);
const today = () => new Date().toISOString().slice(0, 10);
const scopeKey = (s: UsageScope) => `${s.kind}:${s.kind === "global" ? "all" : s.id}:${today()}`;

export class MemoryStore implements Store {
  private users = new Map<string, User>();
  private sessions = new Map<string, Session>();
  private userSessions = new Map<string, string[]>();
  private apiMessages = new Map<string, ApiMessages>();
  private transcripts = new Map<string, TranscriptItem[]>();
  private moments = new Map<string, Map<string, MomentRecord>>();
  private bosses = new Map<string, BossState>();
  private mastery = new Map<string, MasteryMap>();
  private usage = new Map<string, number>();
  readonly events: AppEvent[] = [];

  async getUser(anonId: string) { const u = this.users.get(anonId); return u ? clone(u) : null; }
  async putUser(user: User) { this.users.set(user.anonId, clone(user)); }

  async listSessions(anonId: string): Promise<SessionSummary[]> {
    return (this.userSessions.get(anonId) ?? [])
      .map((id) => this.sessions.get(id))
      .filter((s): s is Session => !!s)
      .map((s) => ({ id: s.id, title: s.title, createdAt: s.createdAt, status: s.status }))
      .sort((a, b) => b.createdAt - a.createdAt);
  }
  async getSession(id: string) { const s = this.sessions.get(id); return s ? clone(s) : null; }
  async putSession(session: Session) {
    this.sessions.set(session.id, clone(session));
    const list = this.userSessions.get(session.anonId) ?? [];
    if (!list.includes(session.id)) this.userSessions.set(session.anonId, [...list, session.id]);
  }

  async getApiMessages(id: string) { return clone(this.apiMessages.get(id) ?? []); }
  async putApiMessages(id: string, messages: ApiMessages) { this.apiMessages.set(id, clone(messages)); }

  async getTranscript(id: string) { return clone(this.transcripts.get(id) ?? []); }
  async putTranscript(id: string, items: TranscriptItem[]) { this.transcripts.set(id, clone(items)); }

  async getMoment(sessionId: string, momentId: string) {
    const m = this.moments.get(sessionId)?.get(momentId); return m ? clone(m) : null;
  }
  async listMoments(sessionId: string) {
    return [...(this.moments.get(sessionId)?.values() ?? [])].map(clone).sort((a, b) => a.createdAt - b.createdAt);
  }
  async putMoment(moment: MomentRecord) {
    const map = this.moments.get(moment.sessionId) ?? new Map<string, MomentRecord>();
    map.set(moment.id, clone(moment));
    this.moments.set(moment.sessionId, map);
  }

  async getBoss(sessionId: string, bossId: string) {
    const b = this.bosses.get(`${sessionId}:${bossId}`); return b ? clone(b) : null;
  }
  async putBoss(boss: BossState) { this.bosses.set(`${boss.sessionId}:${boss.id}`, clone(boss)); }

  async getMastery(anonId: string) { return clone(this.mastery.get(anonId) ?? {}); }
  async putMastery(anonId: string, concept: string, m: ConceptMastery) {
    this.mastery.set(anonId, { ...(this.mastery.get(anonId) ?? {}), [concept]: clone(m) });
  }

  async addUsage(scopes: UsageScope[], microUsd: number) {
    return scopes.map((s) => {
      const k = scopeKey(s); const v = (this.usage.get(k) ?? 0) + microUsd; this.usage.set(k, v); return v;
    });
  }
  async getUsage(scopes: UsageScope[]) { return scopes.map((s) => this.usage.get(scopeKey(s)) ?? 0); }

  async logEvent(event: AppEvent) { this.events.push(clone(event)); }
}

