          ev(D2, 3, "u1", "s3", "moment_answered", { momentId: "q1", concept: "leakage", boss: true, score: 0.5 }),
          ...workMoment(D2, 6, "u2", "s10", "m6", "leakage", { score: 1 }),
        ],
      },
    ]);
