        ev(D2, 4, secret, "sess-SECRET", "boss_started", { name: "Boss SECRET" }),
        ev(D2, 5, secret, "sess-SECRET", "moment_gated", { action: "skip", reason: "free text SECRET" }),
      ]),
    );
